import type { Scope } from "@tinker/core";

/** The main retains named roots in start order and stop controllers with the same names; repeated close calls share one promise. */
export function createScopeClose<T extends Record<string, Scope.RootHandle>>(
  roots: T,
  stop: Record<keyof T, AbortController>,
): () => Promise<void> {
  let closed: Promise<void> | undefined;
  return () => (closed ??= closeRoots(roots, stop));
}

async function closeRoots(
  roots: Record<string, Scope.RootHandle>,
  stop: Record<string, AbortController>,
): Promise<void> {
  const closedReason = new DOMException("The server closed", "AbortError");
  const results: Scope.Result[] = [];
  for (const [name, scope] of Object.entries(roots).toReversed()) {
    stop[name].abort(closedReason);
    results.push(await scope.closed);
  }

  for (const result of results) {
    if (result.status === "failed") throw result.error;
    if (result.teardownErrors?.length) throw result.teardownErrors.at(0);
  }
}

import { tag } from "@tinker/core";
import type { Observe } from "@tinker/core";

/** The command binds render observation; each request borrows it from its own app root. */
export const renderObservation = tag<Observe.Config | undefined>({
  label: "start.renderObservation",
  default: undefined,
});

import { inspect } from "node:util";

import type { ServerEntry } from "./server-entry";

/** Report unhandled process work and close the main before exit; this starts no root. */
export function observeServerPanics(entry: ServerEntry.Handle): void {
  const fail = async (error: unknown) => {
    process.stderr.write(`server: unhandled rejection ${inspect(error)}\n`);
    try {
      await entry.close();
    } finally {
      process.exit(1);
    }
  };

  process.on("unhandledRejection", fail);
  entry.requestContext.scope.onClose(() => {
    process.off("unhandledRejection", fail);
  });
}

import type { ErrorComponentProps } from "@tanstack/react-router";

/**
 * The error text the base's error page may show: the message in dev, and nothing in
 * production, so no server detail reaches a visitor. The server log keeps the error.
 * @param error - From TanStack's error boundary; why: the error a route threw.
 * @param dev - From import.meta.env.DEV; why: only a developer sees the text.
 */
export function errorDetail(error: unknown, dev: boolean): string | undefined {
  if (!dev) return undefined;
  return error instanceof Error ? error.message : String(error);
}

/**
 * Dev only. Start answers a failed render with a bare JSON 500, and that page has no Vite
 * client, so it never sees the fix. This page keeps the body and reloads on the next update.
 * @param request - From the server entry; why: only a browser page load gets the HTML page.
 * @param response - From Start; why: every other response passes through untouched.
 */
export async function devErrorPage(request: Request, response: Response): Promise<Response> {
  const page = request.headers.get("accept")?.includes("text/html");
  const json = response.headers.get("content-type")?.includes("application/json");
  if (response.status !== 500 || !page || !json) return response;
  const body = (await response.text()).replaceAll("&", "&amp;").replaceAll("<", "&lt;");
  return new Response(
    `<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8" />
    <title>Error</title>
    <script type="module">
      import { createHotContext } from "/@vite/client";
      createHotContext("/@tinker/dev-error").on("vite:beforeUpdate", () => location.reload());
    </script>
  </head>
  <body>
    <pre>${body}</pre>
    <p>tinker: the page failed to render; the error is in the terminal.</p>
    <p>Save a fix and this page reloads.</p>
  </body>
</html>`,
    { status: 500, headers: { "content-type": "text/html; charset=utf-8" } },
  );
}

/**
 * The base's error page: a production page shows no error text, and the server log gets the
 * error. It logs to the console because this POC base has no telemetry part yet.
 */
export function TinkerError({ error }: ErrorComponentProps) {
  if (import.meta.env.SSR) console.error("tinker: a route failed on the server:", error);
  const detail = errorDetail(error, import.meta.env.DEV);
  return (
    <main>
      <h1>Something went wrong</h1>
      {detail !== undefined && <pre>{detail}</pre>}
    </main>
  );
}

/** The base's 404 page; a route's own notFoundComponent, or src/router.ts, replaces it. */
export function TinkerNotFound() {
  return (
    <main>
      <h1>Not found</h1>
    </main>
  );
}

import { createRouter } from "@tanstack/react-router";
import type { RouterConstructorOptions, RouterHistory } from "@tanstack/react-router";
import { createIsomorphicFn, getGlobalStartContext } from "@tanstack/react-start";
import { createScope } from "@tinker/core";
import type { Many, Scope } from "@tinker/core";
import { ScopeProvider } from "@tinker/react";
import { abortReasons } from "@tinker/start";

import { routeTree } from "#tinker/routes";

import { renderObservation } from "./observe";
import { TinkerError, TinkerNotFound } from "./panics";

export type RouteTree = typeof routeTree;

export type RouterOptions = (
  routeTree: RouteTree,
) => Partial<
  Omit<
    RouterConstructorOptions<RouteTree, "never", false, RouterHistory, Record<string, unknown>>,
    "routeTree" | "Wrap" | "context"
  >
>;

type Parts = Pick<
  typeof import("@tinker/start/router"),
  "sync" | "telemetry" | "pageEvents" | "tabStop"
> & {
  extensions: Many<Scope.Extension<unknown>>;
  router: RouterOptions;
};

/** The command passes optional parts; only browser tabs own a telemetry root. */
export async function createRouterEntry({
  sync,
  telemetry,
  pageEvents,
  tabStop,
  extensions,
  router,
}: Parts) {
  const readTelemetry = createIsomorphicFn()
    .server(() => ({
      observe: () => getGlobalStartContext()?.scope?.resolve(renderObservation),
      close: undefined,
    }))
    .client(async () => {
      const toolStop = new AbortController();
      const tools = createScope({
        signal: toolStop.signal,
        extensions: telemetry.extensions,
        tags: telemetry.tags,
      });
      await tools.ready;
      return {
        observe() {
          return tools.resolve(telemetry.observe);
        },
        close() {
          toolStop.abort(abortReasons.closed);
          return tools.closed;
        },
      };
    });

  const readPage = createIsomorphicFn()
    .server((): EventTarget | undefined => undefined)
    .client(() => window);

  const reading = readTelemetry();
  const tools = reading instanceof Promise ? await reading : reading;

  const stop = new AbortController();
  const app = createScope({
    signal: stop.signal,
    extensions: [sync.extensions, extensions],
    observe: tools.observe(),
    tags: [tabStop(stop.signal), pageEvents(readPage())],
  });

  let tab: Awaited<ReturnType<typeof sync.router.factory>>;
  try {
    await app.ready;
    tab = app.resolve(sync.router);
  } catch (error) {
    stop.abort(abortReasons.closed);
    await app.closed;
    await tools.close?.();
    throw error;
  }

  let closed: Promise<void> | undefined;
  const close = () =>
    (closed ??= (async () => {
      stop.abort(abortReasons.closed);
      const end = await app.closed;
      const toolEnd = await tools.close?.();
      for (const result of [end, toolEnd]) {
        if (result?.status === "failed") throw result.error;
        if (result?.teardownErrors?.length) throw result.teardownErrors.at(0);
      }
    })());

  tab.bind(close);
  if (import.meta.hot) import.meta.hot.dispose(close);

  return Object.assign(
    createRouter({
      scrollRestoration: true,
      defaultErrorComponent: TinkerError,
      defaultNotFoundComponent: TinkerNotFound,
      ...router(routeTree),
      ...tab.options,
      routeTree,
      Wrap: ({ children }) => <ScopeProvider scope={app}>{children}</ScopeProvider>,
    }),
    { close },
  );
}

/** TanStack binds route types to the copied router entry. */
declare module "@tanstack/react-router" {
  interface Register {
    router: Awaited<ReturnType<typeof createRouterEntry>>;
  }
}

import {
  createStartHandler as createStart,
  defaultStreamHandler as renderStream,
} from "@tanstack/react-start/server";
import type { Observe, Scope } from "@tinker/core";
import { raise } from "@tinker/start";
import { retainRender } from "@tinker/start/server";

import { devErrorPage } from "./panics";
import type { createRouterEntry } from "./router-entry";

/** The command retains both roots; Start borrows context and observation. */
export declare namespace ServerEntry {
  type Next = (request: Request) => Promise<Response>;
  type Handle = {
    requestContext: { scope: Scope.Handle };
    renderObserve: Observe.Config;
    close(): Promise<void>;
    fetch?(request: Request, next: Next): Promise<Response> | Response;
  };
}

/** Render over the supplied app; request bodies retain each render's close. */
export function createServerHandler(app: ServerEntry.Handle) {
  const renderRequest = createStart(async (context) => {
    const router: typeof context.router & {
      close?: Awaited<ReturnType<typeof createRouterEntry>>["close"];
    } = context.router;
    if (typeof router.close !== "function") raise("StartScopeMissing", {});
    retainRender(context.request, router.close);

    try {
      return await renderStream(context);
    } catch (error) {
      await router.close();
      throw error;
    }
  });

  return {
    ...app,
    fetch(request: Request) {
      const next = async (forwarded: Request) => {
        const response = await renderRequest(forwarded, { context: app.requestContext });
        return import.meta.env.DEV ? devErrorPage(forwarded, response) : response;
      };
      return app.fetch ? app.fetch(request, next) : next(request);
    },
  };
}

import { createCsrfMiddleware, createStart } from "@tanstack/react-start";
import { startRequests } from "@tinker/start";

/** The command passes app options; CSRF and requests run before its middleware. */
export function createStartEntry(app: { getOptions: Parameters<typeof createStart>[0] }) {
  const csrf = createCsrfMiddleware({ filter: (ctx) => ctx.handlerType === "serverFn" });
  let options: ReturnType<typeof readOptions> | undefined;

  async function readOptions() {
    const own = await app.getOptions();
    return {
      ...own,
      requestMiddleware: [csrf, startRequests.middleware, ...(own.requestMiddleware ?? [])],
    };
  }

  return createStart(() => (options ??= readOptions()));
}

import { createStartEntry } from "~/base/start-entry";

import { startInstance as app } from "@/start";

export const startInstance = createStartEntry(app);

import { createStart } from "@tanstack/react-start";

/** The base's empty start file: an app with no src/start.ts adds no Start options. */
export const startInstance = createStart(() => ({}));
